VALIDATION_CLASSES = frozenset(('environment-lease', 'archive-layout', 'archive-safe-mode', 'archive-content', 'runtime-proof'))


class GateFailure(RuntimeError):
    def __init__(self, category):
        if category not in VALIDATION_CLASSES:
            raise ValueError('Unknown validation class')
        super().__init__('Verification refused')
        self.category = category


def classed(category, operation, *args, **kwargs):
    try:
        return operation(*args, **kwargs)
    except GateFailure:
        raise
    except BaseException:
        # Class only, never an exception message, filename, value or traceback.
        raise GateFailure(category) from None


def require(condition):
    if not condition:
        raise RuntimeError('Verification refused')


def load_manifest(text, digest, kind, count, total):
    raw = text.encode('utf-8')
    require(hashlib.sha256(raw).hexdigest() == digest)
    value = json.loads(raw)
    require(value['format'] == kind and value['version'] == 1 and value['commit'] == COMMIT
            and value['gitTree'] == TREE and value['repository'] == REPOSITORY
            and value['fileCount'] == count and value['totalBytes'] == total)
    files, directories = value['files'], value['directories']
    require(len(files) == count and len({entry['path'] for entry in files}) == count
            and len(directories) == len(set(directories)))
    require(sum(entry['size'] for entry in files) == total)
    for path in [entry['path'] for entry in files] + directories:
        parsed = PurePosixPath(path)
        require(isinstance(path, str) and not parsed.is_absolute() and str(parsed) == path
                and '..' not in parsed.parts and '\x00' not in path and path != '.')
    for entry in files:
        require(entry['type'] == 'regular' and entry['gitMode'] in ('100644', '100755')
                and type(entry['size']) is int and 0 <= entry['size'] <= 8 * 1024 * 1024
                and re.fullmatch('[a-f0-9]{64}', entry['sha256'])
                and re.fullmatch('[a-f0-9]{40}', entry['gitBlob']))
    expected_dirs = {str(parent) for entry in files for parent in PurePosixPath(entry['path']).parents if str(parent) != '.'}
    require(set(directories) == expected_dirs)
    return value


def manifests():
    archive = load_manifest(ARCHIVE_MANIFEST_TEXT, ARCHIVE_MANIFEST_SHA256,
                            'nestlet-trusted-git-tree-manifest', 315, 9465233)
    runtime = load_manifest(RUNTIME_MANIFEST_TEXT, RUNTIME_MANIFEST_SHA256,
                            'nestlet-runtime-source-copy-manifest', 31, 478864)
    original = {entry['path']: entry for entry in archive['files']}
    require(all(original.get(entry['path']) == entry for entry in runtime['files']))
    return archive, runtime


def fingerprint(info):
    return (info.st_dev, info.st_ino, info.st_mode, info.st_uid, info.st_gid,
            info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def safe_directory(info, uid, root=False):
    # Descendants are reached only through the verified private0700 root.
    # Canonical git tar group-write bits grant no pathname access there.
    require(stat.S_ISDIR(info.st_mode) and info.st_uid == uid and info.st_gid == os.getegid()
            and not stat.S_IMODE(info.st_mode) & 0o7002)
    if root:
        require(stat.S_IMODE(info.st_mode) == 0o700)


def safe_file(info, entry, uid):
    mode = stat.S_IMODE(info.st_mode)
    require(stat.S_ISREG(info.st_mode) and info.st_uid == uid and info.st_gid == os.getegid() and info.st_nlink == 1
            and not mode & 0o7002 and mode & 0o400)
    classed('archive-content', require, info.st_size == entry['size'])
    require(bool(mode & 0o111) == (entry['gitMode'] == '100755'))
    if entry['gitMode'] == '100755':
        require(mode & 0o100)


def open_archive_root(path, uid):
    require(path.is_absolute() and str(path) == os.path.normpath(path))
    fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        parts = path.parts[1:]
        for index, name in enumerate(parts):
            child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            os.close(fd);fd = child
            info = os.fstat(fd)
            sticky_root_ancestor = index < len(parts)-1 and info.st_uid == 0 and info.st_mode & stat.S_ISVTX
            require(stat.S_ISDIR(info.st_mode) and info.st_uid in (0, uid)
                    and (not info.st_mode & 0o022 or sticky_root_ancestor))
        safe_directory(os.fstat(fd), uid, root=True)
        return fd
    except BaseException:
        os.close(fd)
        raise


def enumerate_archive(root_fd, manifest, uid):
    expected = {entry['path']: entry for entry in manifest['files']}
    directories = set(manifest['directories'])
    files_seen, dirs_seen = {}, {'': fingerprint(os.fstat(root_fd))}
    maximum = len(expected) + len(directories)
    seen = 0
    def walk(fd, prefix):
        nonlocal seen
        classed('archive-safe-mode', safe_directory, os.fstat(fd), uid, root=not prefix)
        with os.scandir(fd) as iterator:
            names = []
            for entry in iterator:
                seen += 1;require(seen <= maximum)
                names.append(entry.name)
        for name in sorted(names):
            relative = prefix + name
            require(relative in expected or relative in directories)
            info = os.stat(name, dir_fd=fd, follow_symlinks=False)
            if relative in expected:
                classed('archive-safe-mode', safe_file, info, expected[relative], uid)
                files_seen[relative] = fingerprint(info)
            else:
                classed('archive-safe-mode', safe_directory, info, uid)
                child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
                try:
                    require(fingerprint(os.fstat(child)) == fingerprint(info))
                    dirs_seen[relative] = fingerprint(info)
                    walk(child, relative + '/')
                finally:
                    os.close(child)
    walk(root_fd, '')
    require(set(files_seen) == set(expected) and set(dirs_seen)-{''} == directories)
    return files_seen, dirs_seen


def hash_archive_file(root_fd, entry, before_files, before_dirs, uid):
    descriptors = []
    parent_fd = root_fd
    pieces = entry['path'].split('/')
    prefix = ''
    try:
        for name in pieces[:-1]:
            prefix = prefix + '/' + name if prefix else name
            fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent_fd)
            descriptors.append(fd);parent_fd = fd
            require(fingerprint(os.fstat(fd)) == before_dirs[prefix])
        fd = os.open(pieces[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent_fd)
        descriptors.append(fd)
        info = os.fstat(fd);classed('archive-safe-mode', safe_file, info, entry, uid)
        require(fingerprint(info) == before_files[entry['path']])
        digest = hashlib.sha256();read = 0
        while True:
            chunk = os.read(fd, min(131072, entry['size'] + 1 - read))
            if not chunk:
                break
            read += len(chunk);require(read <= entry['size']);digest.update(chunk)
        require(read == entry['size'] and digest.hexdigest() == entry['sha256'])
        require(fingerprint(os.fstat(fd)) == fingerprint(info))
        require(fingerprint(os.stat(pieces[-1], dir_fd=parent_fd, follow_symlinks=False)) == fingerprint(info))
    finally:
        for fd in reversed(descriptors):
            os.close(fd)


def verify_archive(path, manifest, uid):
    root_fd = classed('archive-safe-mode', open_archive_root, path, uid)
    try:
        before_files, before_dirs = classed('archive-layout', enumerate_archive, root_fd, manifest, uid)
        # Enumeration of every entry completed before any source file bytes are read.
        for entry in manifest['files']:
            classed('archive-content', hash_archive_file, root_fd, entry, before_files, before_dirs, uid)
        classed('archive-layout', require, classed('archive-layout', enumerate_archive, root_fd, manifest, uid) == (before_files, before_dirs))
        final_fd = classed('archive-safe-mode', open_archive_root, path, uid)
        try:
            classed('archive-layout', require, fingerprint(os.fstat(final_fd)) == before_dirs[''])
        finally:
            os.close(final_fd)
    finally:
        os.close(root_fd)


RUNTIME_CHECK = r'''
import {constants,openSync,readSync,closeSync,fstatSync,lstatSync} from "node:fs";
import {createHash} from "node:crypto";
const manifest=JSON.parse(process.argv[1]);
const root=__RUNTIME_ROOT__,uid=BigInt(__RUNTIME_UID__),gid=BigInt(__RUNTIME_GID__);
const fail=()=>{throw Error("Verification refused");};
const stamp=info=>[info.dev,info.ino,info.mode,info.uid,info.gid,info.nlink,info.size,info.mtimeNs,info.ctimeNs].map(String).join(":");
// Caller proves readonly root plus no /app overlays before this program runs.
// Canonical COPY group-write metadata is ineffective under that immutable mount.
const directory=info=>{if(!info.isDirectory()||![0n,uid].includes(info.uid)||![0n,gid].includes(info.gid)||(info.mode&0o7002n))fail();};
const rootFd=openSync(root,constants.O_RDONLY|constants.O_DIRECTORY|constants.O_NOFOLLOW),observed=[];
try{
 directory(fstatSync(rootFd,{bigint:true}));
 for(const entry of manifest.files){
  const names=entry.path.split("/");if(names.some(name=>!name||name==="."||name===".."))fail();
  const fds=[];let parent=rootFd;
  try{
   for(const name of names.slice(0,-1)){const fd=openSync(`/proc/self/fd/${parent}/${name}`,constants.O_RDONLY|constants.O_DIRECTORY|constants.O_NOFOLLOW);fds.push(fd);parent=fd;directory(fstatSync(fd,{bigint:true}));}
   const location=`/proc/self/fd/${parent}/${names.at(-1)}`;
   const fd=openSync(location,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);fds.push(fd);
   const info=fstatSync(fd,{bigint:true}),executable=entry.gitMode==="100755";
   if(!info.isFile()||info.uid!==uid||info.gid!==gid||info.nlink!==1n||info.size!==BigInt(entry.size)||(info.mode&0o7002n)||!(info.mode&0o400n)||Boolean(info.mode&0o111n)!==executable||(executable&&!(info.mode&0o100n)))fail();
   const hash=createHash("sha256"),buffer=Buffer.alloc(131072);let n,total=0;
   while((n=readSync(fd,buffer,0,buffer.length,null))){total+=n;if(total>entry.size)fail();hash.update(buffer.subarray(0,n));}
   if(total!==entry.size||hash.digest("hex")!==entry.sha256||stamp(fstatSync(fd,{bigint:true}))!==stamp(info)||stamp(lstatSync(location,{bigint:true}))!==stamp(info))fail();
   observed.push([entry.path,stamp(info)]);
  }finally{for(const fd of fds.reverse())closeSync(fd);}
 }
 // Read-only image root plus per-file pre/post identity checks; generated next/
 // and dependency bytes are not source-equivalent and are not inspected here.
 if(observed.length!==manifest.fileCount)fail();
 console.log("PASS");
}finally{closeSync(rootFd);}
'''


def runtime_program(root='/app', uid=1000, gid=None):
    # Production uses the approved node uid/gid1000; explicit values serve local fixtures only.
    return RUNTIME_CHECK.replace('__RUNTIME_ROOT__', json.dumps(root)).replace('__RUNTIME_UID__', str(uid)).replace('__RUNTIME_GID__', str(uid if gid is None else gid))


def command(arguments):
    env = dict(os.environ, DOCKER_HOST='unix:///var/run/docker.sock')
    env.pop('DOCKER_CONTEXT', None)
    completed = subprocess.run(arguments, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                               stderr=subprocess.DEVNULL, env=env, timeout=30)
    require(completed.returncode == 0 and len(completed.stdout) <= 65536)
    return completed.stdout.decode('utf-8').strip()


def inspect_runtime():
    ids = command(['docker', 'ps', '-aq', '--filter', 'label=com.docker.compose.project=nestlet']).split()
    require(len(ids) == 1 and re.fullmatch('[a-f0-9]{12,64}', ids[0]))
    fmt = ('{"image":{{json .Config.Image}},"imageId":{{json .Image}},'
           '"project":{{json (index .Config.Labels "com.docker.compose.project")}},'
           '"service":{{json (index .Config.Labels "com.docker.compose.service")}},'
           '"running":{{json .State.Running}},"health":{{json .State.Health.Status}},'
           '"readOnly":{{json .HostConfig.ReadonlyRootfs}},"ports":{{json .HostConfig.PortBindings}},'
           '"mounts":{{json .Mounts}},"workingDir":{{json .Config.WorkingDir}},'
           '"command":{{json .Config.Cmd}},"user":{{json .Config.User}},'
           '"tmpfs":{{json .HostConfig.Tmpfs}},"privileged":{{json .HostConfig.Privileged}},'
           '"capDrop":{{json .HostConfig.CapDrop}},"capAdd":{{json .HostConfig.CapAdd}},'
           '"security":{{json .HostConfig.SecurityOpt}}}')
    item = json.loads(command(['docker', 'inspect', '--format', fmt, ids[0]]))
    require(item['project'] == 'nestlet' and item['service'] == 'nestlet'
            and item['image'] == 'nestlet:' + COMMIT and re.fullmatch('sha256:[a-f0-9]{64}', item['imageId'])
            and item['running'] is True and item['health'] == 'healthy' and item['readOnly'] is True
            and item['workingDir'] == '/app' and item['command'] == ['node', 'server.js'] and item['user'] in ('node', '1000', '1000:1000'))
    require(item['ports'] == {'4173/tcp': [{'HostIp': '127.0.0.1', 'HostPort': '4173'}]})
    require(not item['privileged'] and 'ALL' in (item['capDrop'] or []) and not item['capAdd']
            and 'no-new-privileges:true' in (item['security'] or []))
    require(set((item.get('tmpfs') or {}).keys()) <= {'/tmp'})
    require(all(entry['Destination'] == '/tmp' for entry in item['mounts'] if entry['Type'] == 'tmpfs'))
    mounts = [entry for entry in item['mounts'] if entry['Type'] != 'tmpfs']
    require(len(mounts) == 1 and mounts[0]['Type'] == 'volume' and mounts[0]['Name'] == 'nestlet_case_data'
            and mounts[0]['Destination'] == '/data' and mounts[0]['RW'] is True)
    volume = json.loads(command(['docker', 'volume', 'inspect', 'nestlet_case_data', '--format', '{{json .}}']))
    labels = volume.get('Labels', {})
    require(volume['Name'] == 'nestlet_case_data' and volume['Driver'] == 'local' and not volume.get('Options')
            and labels.get('com.docker.compose.project') == 'nestlet'
            and labels.get('com.docker.compose.volume') == 'case_data'
            and labels.get('com.nestlet.purpose') == 'private-case-storage')
    require(command(['docker', 'image', 'inspect', '--format', '{{.Id}}', item['image']]) == item['imageId'])
    return ids[0], item['imageId']


HEADER_GATE = '\nimport {constants,openSync,readSync,closeSync,fstatSync,lstatSync} from "node:fs";\nconst path="/data/nestlet.sqlite";\nconst fail=()=>{throw Error("Private SQLite metadata unavailable");};\nconst privateMode=(entry,mode)=>entry.uid===process.geteuid()&&(entry.mode&0o777)===mode;\nconst dir=lstatSync("/data");if(!dir.isDirectory()||!privateMode(dir,0o700))fail();\nconst busy=()=>["-wal","-journal"].some(suffix=>{try{const info=lstatSync(path+suffix);return !info.isFile()||info.size!==0;}catch(error){if(error.code==="ENOENT")return false;throw error;}});\nif(busy())fail();\nconst fd=openSync(path,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);\ntry{\n  const initial=fstatSync(fd);if(!initial.isFile()||initial.nlink!==1||!privateMode(initial,0o600)||initial.size<100)fail();\n  const header=Buffer.alloc(100),again=Buffer.alloc(100);\n  if(readSync(fd,header,0,100,0)!==100||readSync(fd,again,0,100,0)!==100||!header.equals(again))fail();\n  const final=fstatSync(fd),entry=lstatSync(path);\n  if(initial.ino!==final.ino||initial.dev!==final.dev||initial.size!==final.size||initial.mtimeMs!==final.mtimeMs||entry.ino!==initial.ino||entry.dev!==initial.dev||busy())fail();\n  if(!header.subarray(0,16).equals(Buffer.from("SQLite format 3\\0"))||header[18]!==1||header[19]!==1)fail();\n  if(header.readUInt32BE(60)!==4||header.readUInt32BE(68)!==0x4e53544c)fail();console.log("PASS");\n}finally{closeSync(fd);}\n'


def verify_marker(path, uid):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        before = os.fstat(fd)
        require(stat.S_ISREG(before.st_mode) and before.st_uid == uid and before.st_nlink == 1
                and stat.S_IMODE(before.st_mode) == 0o600 and before.st_size <= 64)
        marker = os.read(fd, 65)
        require(marker.strip() == b'nestlet-managed-stage-v1')
        require(fingerprint(os.fstat(fd)) == fingerprint(before)
                and fingerprint(path.lstat()) == fingerprint(before))
    finally:
        os.close(fd)


def verify_host(mode='all', lease_fd=None):
    require(mode in ('all', 'archive', 'runtime'))
    archive_manifest, runtime_manifest = manifests()
    uid = os.geteuid()
    for path in [BASE, BASE / 'releases', BASE / 'shared']:
        safe_directory(path.lstat(), uid, root=True)
    verify_marker(BASE / '.nestlet-managed', uid)
    current = BASE / 'current'
    require(current.is_symlink() and os.readlink(current) == str(ARCHIVE))
    pointer = fingerprint(current.lstat())
    lock = BASE / '.incremental-release.lock'
    # Standalone: read-only shared lease. Upgrade: inherit/retain the exact fd9
    # open-file description, confirming its exclusive lease without unlocking it.
    fd = os.dup(lease_fd) if lease_fd is not None else os.open(lock, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        info = os.fstat(fd)
        require(stat.S_ISREG(info.st_mode) and info.st_uid == uid and info.st_nlink == 1
                and stat.S_IMODE(info.st_mode) == 0o600 and fingerprint(lock.lstat()) == fingerprint(info))
        fcntl.flock(fd, (fcntl.LOCK_EX if lease_fd is not None else fcntl.LOCK_SH) | fcntl.LOCK_NB)
        verify_archive(ARCHIVE, archive_manifest, uid)
        if mode != 'archive':
            def runtime_proof():
                container, image = inspect_runtime()
                require(command(['docker', 'exec', '--user', '1000:1000', container, 'node', '--input-type=module', '-e', runtime_program(), json.dumps(runtime_manifest, separators=(',', ':'))]) == 'PASS')
                require(command(['docker', 'exec', '--user', '1000:1000', container, 'node', '--input-type=module', '-e', HEADER_GATE]) == 'PASS')
                require(inspect_runtime() == (container, image))
            classed('runtime-proof', runtime_proof)
        require(os.readlink(current) == str(ARCHIVE) and fingerprint(current.lstat()) == pointer)
    finally:
        os.close(fd)


def emit_gate(operation):
    try:
        operation()
    except BaseException as error:
        category = error.category if isinstance(error, GateFailure) and error.category in VALIDATION_CLASSES else 'environment-lease'
        print('Nestlet verification failed [' + category + '].')
        return 1
    print('Nestlet verification passed.')
    return 0


if __name__ == '__main__':
    sys.exit(emit_gate(verify_host))
